// Final topic-stage contract validator and ledger adapter.
const raw = $input.first().json.text ?? '';
const clean = String(raw).replace(/^\s*\`\`\`json\s*/i, '').replace(/\`\`\`\s*$/,'').trim();
let parsed;
try { parsed = JSON.parse(clean); } catch (error) { throw new Error('[Topic Triage] invalid JSON: ' + error.message); }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || Object.keys(parsed).length !== 1 || !Array.isArray(parsed.tasks)) throw new Error('[Topic Triage] expected exactly { tasks: [...] }.');

const context = $('Aggregate Intel (Fan-in)').first().json;
const allowedUrls = new Set((context.materials || []).map(material => material.url));
const headings = ['[事件定义]', '[证据分层]', '[时效与素材边界]', '[研究价值]', '[待验证问题]', '[潜在叙事类型]', '[禁止提前断言]'];
if (parsed.tasks.length === 0) throw new Error('[Topic Triage] zero candidates: no publishable topic; return to discovery with different scope.');
if (parsed.tasks.length !== context.target_count) throw new Error('[Topic Triage] expected exactly ' + context.target_count + ' candidates but received ' + parsed.tasks.length + '; never pad a shortfall and never exceed the requested count.');

const seenTitles = new Set();
const seenBriefs = new Set();
return parsed.tasks.map((task, index) => {
  const keys = Object.keys(task || {}).sort().join(',');
  const validKeys = keys === 'intel_content,source_urls,title' || keys === 'intel_content,source_urls,status,title';
  if (!validKeys || typeof task.title !== 'string' || !task.title.trim() || ('status' in task && task.status !== 'pending') || !Array.isArray(task.source_urls) || task.source_urls.length === 0 || typeof task.intel_content !== 'string') throw new Error('[Topic Triage] task ' + (index + 1) + ' violates its required fields.');
  const normalizedTitle = task.title.trim().toLowerCase().replace(/\s+/g, ' ');
  if (seenTitles.has(normalizedTitle)) throw new Error('[Topic Triage] task ' + (index + 1) + ' duplicates an earlier topic title after normalization.');
  seenTitles.add(normalizedTitle);
  const briefIdentity = JSON.stringify([task.intel_content.replace(/\s+/g, ' ').trim(), [...task.source_urls].sort()]);
  if (seenBriefs.has(briefIdentity)) throw new Error('[Topic Triage] task ' + (index + 1) + ' duplicates a prior topic brief with the same source set.');
  seenBriefs.add(briefIdentity);
  if (new Set(task.source_urls).size !== task.source_urls.length || task.source_urls.some(url => typeof url !== 'string' || !allowedUrls.has(url))) throw new Error('[Topic Triage] task ' + (index + 1) + ' cites a URL outside retrieved materials.');
  const brief = task.intel_content;
  if (!brief.startsWith('LCW_TOPIC_BRIEF_V2')) throw new Error('[Topic Triage] task ' + (index + 1) + ' lacks LCW_TOPIC_BRIEF_V2.');
  let last = -1;
  for (const heading of headings) {
    const first = brief.indexOf(heading);
    if (first < 0 || first <= last || first !== brief.lastIndexOf(heading)) throw new Error('[Topic Triage] task ' + (index + 1) + ' has invalid brief headings.');
    last = first;
  }
  const refs = [...brief.matchAll(/\[S(\d+)\]/g)].map(match => Number(match[1]));
  if (refs.length === 0 || refs.some(ref => ref < 1 || ref > task.source_urls.length)) throw new Error('[Topic Triage] task ' + (index + 1) + ' has invalid local source references.');
  return { json: { title: task.title.trim(), url: JSON.stringify(task.source_urls), intel_content: brief, status: 'pending', created_at: new Date().toISOString(), candidate_count: parsed.tasks.length } };
});

// Topic-stage context builder. Keep human context and provenance intact.
const items = $input.all();
const seenUrls = new Set();
const materials = [];

function laneFromSource(source) {
  const value = String(source || '').toLowerCase();
  if (value.includes('aihot')) return 'aihot';
  if (value.startsWith('rss -')) return 'rss';
  if (value.includes('zhihu')) return 'zhihu';
  return 'unknown';
}

for (const item of items) {
  const intel = item.json?.intel;
  if (!Array.isArray(intel)) continue;
  for (const candidate of intel) {
    const rawUrl = String(candidate?.url || candidate?.link || '').trim();
    const title = typeof candidate?.title === 'string' ? candidate.title.trim() : '';
    if (!rawUrl || !title || seenUrls.has(rawUrl)) continue;
    seenUrls.add(rawUrl);
    const source = candidate.source || 'Unknown';
    materials.push({
      item_id: 'I' + String(materials.length + 1).padStart(3, '0'),
      lane: laneFromSource(source),
      source,
      publisher: typeof candidate.publisher === 'string' && candidate.publisher.trim() ? candidate.publisher.trim() : null,
      title,
      url: rawUrl,
      snippet: typeof candidate.snippet === 'string' ? candidate.snippet : '',
      published_at: typeof candidate.published_at === 'string' ? candidate.published_at :
        (typeof candidate.pubDate === 'string' ? candidate.pubDate : null),
      origin_url: typeof candidate.origin_url === 'string' ? candidate.origin_url : null,
      discoveries: Array.isArray(candidate.discoveries) ? candidate.discoveries : null
    });
  }
}
if (materials.length === 0) throw new Error('[Topic Aggregator] no usable source material returned.');

const input = $('Normalize Inputs').first().json;
const planned = $('Parse Router Output').all().map(item => item.json);
const laneHealth = planned.map(({ target }) => {
  const count = materials.filter(material => material.lane === target).length;
  return { target, usable_item_count: count, status: count > 0 ? 'returned_items' : 'no_usable_items' };
});
const sourceDistribution = {};
for (const material of materials) sourceDistribution[material.source] = (sourceDistribution[material.source] || 0) + 1;

return { json: {
  topic_intent: input.topic_intent,
  editor_note_raw: input.editor_note_raw,
  aihot_query_seed: input.aihot_query_seed,
  timeframe: input.timeframe,
  target_count: input.target_count,
  run_timestamp: input.run_timestamp,
  lane_health: laneHealth,
  materials,
  intel: materials,
  intel_count: materials.length,
  source_distribution: sourceDistribution
} };

const tiers = [['https://openai.com/news/rss.xml'],['https://aws.amazon.com/blogs/machine-learning/feed/'],['https://simonwillison.net/atom/everything/'],['https://www.technologyreview.com/feed/'],['https://krebsonsecurity.com/feed/']];
const stamp = $('Normalize Inputs').first().json.run_timestamp || new Date().toISOString();
const d = new Date(stamp);
const seed = Math.floor(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) / 86400000);
return tiers.map((tier, index) => ({ json: { url: tier[(seed + index) % tier.length] } }));

const raw = $input.first().json.text ?? $input.first().json.output ?? '';
const clean = String(raw).replace(/^\\s*```json\\s*/i, '').replace(/```\\s*$/,'').trim();
let parsed;
try { parsed = JSON.parse(clean); } catch (error) { throw new Error('[Topic Router] invalid JSON: ' + error.message); }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || Object.keys(parsed).length !== 1 || !Array.isArray(parsed.tasks)) throw new Error('[Topic Router] expected exactly { tasks: [...] }.');
const input = $('Normalize Inputs').first().json;
const supported = new Set(['auto', 'aihot', 'rss', 'zhihu']);
if (!supported.has(input.source_lane)) throw new Error('[Topic Router] unsupported source_lane: ' + input.source_lane);
if (parsed.tasks.length < 1 || parsed.tasks.length > 3) throw new Error('[Topic Router] tasks must contain one to three items.');
const seen = new Set();
for (const task of parsed.tasks) {
 if (!task || typeof task !== 'object' || Array.isArray(task) || Object.keys(task).length !== 2 || !['aihot','rss','zhihu'].includes(task.target) || typeof task.query !== 'string' || !task.query.trim()) throw new Error('[Topic Router] every task must be exactly {target, query}.');
 if (task.target === 'rss' && task.query !== 'daily') throw new Error('[Topic Router] rss query must be exactly daily.');
 if (seen.has(task.target)) throw new Error('[Topic Router] duplicate target: ' + task.target);
 seen.add(task.target);
}
if (input.source_lane === 'auto' && (!seen.has('aihot') || !seen.has('rss'))) throw new Error('[Topic Router] auto requires exactly one aihot task and one rss task.');
if (input.source_lane !== 'auto' && (seen.size !== 1 || !seen.has(input.source_lane))) throw new Error('[Topic Router] explicit lane must emit exactly its requested target.');
return parsed.tasks.map(task => ({json:{target:task.target,query:task.query.trim()}}));

// Official Zhihu Open Platform hot list (developer.zhihu.com).
// Shape: { Code, Message, Data: { Items: [ { Title, Url, ThumbnailUrl, Summary } ], Total } }
const items = $input.item.json.Data?.Items || [];
const candidates = items.map((it) => ({
  source: 'Zhihu Hot List',
  title: it.Title || '未知标题',
  url: it.Url || '',
  snippet: it.Summary || '知乎热榜'
}));
return { json: { intel: candidates } };

const input = $('Normalize Inputs').first().json;
const timeframe = input.timeframe || 'any';
const now = Date.now();
const match = timeframe.match(/^(\d+)([hd])$/);
const cutoff = match ? now - Number(match[1]) * (match[2] === 'h' ? 3600000 : 86400000) : 0;
const list = value => Array.isArray(value) ? value : (value == null ? [] : [value]);
const scalar = value => Array.isArray(value) ? scalar(value[0]) : (typeof value === 'string' ? value : (value && typeof value === 'object' ? String(value._ || '') : ''));
const clean = value => scalar(value).replace(/<[^>]*>/g, ' ').replace(/\\s+/g, ' ').trim().slice(0, 300);
const intel = [];
const perSourceCount = new Map();
const maxItemsPerSource = 12;
for (const record of $input.all()) {
  const root = record.json.rss || record.json.feed;
  if (!root) continue;
  const channel = list(root.channel)[0] || {};
  const feedTitle = clean(channel.title) || clean(root.title) || 'RSS';
  const entries = record.json.rss ? list(channel.item) : list(root.entry);
  for (const entry of entries) {
    const title = clean(entry.title);
    let url = '';
    if (record.json.rss) url = scalar(entry.link);
    else { const links = list(entry.link); const link = links[0]; url = typeof link === 'object' ? String(link.href || '') : scalar(link); }
    if (!title || !url) continue;
    const dateRaw = scalar(entry.pubDate) || scalar(entry.updated) || scalar(entry.published);
    const published = Date.parse(dateRaw);
    if (Number.isFinite(published) && (published > now + 3600000 || (cutoff && published < cutoff))) continue;
    if (!Number.isFinite(published) && cutoff) continue;
    const source = 'RSS - ' + feedTitle;
    if ((perSourceCount.get(source) || 0) >= maxItemsPerSource) continue;
    perSourceCount.set(source, (perSourceCount.get(source) || 0) + 1);
    intel.push({source, title, url, published_at: dateRaw, snippet: clean(entry.description) || clean(entry.summary) || clean(entry.content)});
  }
}
return { json: { intel: intel.slice(0, 60), count: intel.length } };

const input = $input.first().json;
const body = input.body;
const data = body && typeof body === 'object' && Object.keys(body).length > 0 ? body : input;
const topicIntent = data.topic_intent || data.query || '';
if (typeof topicIntent !== 'string' || !topicIntent.trim()) throw new Error('[Topic Input] missing required topic_intent.');
const sourceLane = data.source_lane || 'auto';
if (!['auto', 'aihot', 'rss', 'zhihu'].includes(sourceLane)) throw new Error('[Topic Input] source_lane must be auto, aihot, rss, or zhihu.');
const rawCount = data.target_count;
const countMissing = rawCount === undefined || rawCount === null || (typeof rawCount === 'string' && rawCount.trim() === '');
let targetCount = 3;
if (!countMissing) {
  const providedCount = typeof rawCount === 'number' ? rawCount : (typeof rawCount === 'string' && /^\d+$/.test(rawCount.trim()) ? Number(rawCount.trim()) : NaN);
  if (!Number.isSafeInteger(providedCount) || providedCount < 1) throw new Error('[Topic Input] target_count must be a positive safe integer when provided.');
  targetCount = providedCount;
}
const entitySeeds = Array.isArray(data.entity_seeds) ? data.entity_seeds.filter(value => typeof value === 'string' && value.trim()).map(value => value.trim()).slice(0, 3) : [];
const editorNote = typeof data.editor_note_raw === 'string' ? data.editor_note_raw.trim() : '';
const aihotSeed = typeof data.aihot_query_seed === 'string' && data.aihot_query_seed.trim() ? data.aihot_query_seed.trim() : null;
return { json: { topic_intent: topicIntent.trim(), editor_note_raw: editorNote, aihot_query_seed: aihotSeed, timeframe: typeof data.timeframe === 'string' && data.timeframe.trim() ? data.timeframe.trim() : '72h', target_count: targetCount, source_lane: sourceLane, entity_seeds: entitySeeds, run_timestamp: typeof data.run_timestamp === 'string' && data.run_timestamp ? data.run_timestamp : new Date().toISOString() } };

// AIHOT public v1 API -> standard intel shape.
// Query the FULL pool over a 7d window: the curated `selected` pool at 24h is too
// narrow (probed: q='AI Agent' selected/24h -> 0, all/24h -> 10, selected/7d -> 10).
// We still surface AIHOT's own curation via the `selected` flag in the source label.
const items = $input.item.json.items || [];
const intel = items.map((it) => ({
  source: it.selected ? 'AIHOT 精选' : 'AIHOT',
  title: it.title || it.originalTitle || '未知标题',
  url: (it.links && (it.links.aihot || it.links.original)) || '',
  snippet: it.summary || '',
  published_at: it.publishedAt ?? null
}));
return { json: { intel } };

const emptyRss = '<rss><channel><title>Unavailable RSS source</title></channel></rss>';
return $input.all().map(item => {
  const data = item.json && item.json.data;
  return { json: { data: typeof data === 'string' && data.trim() ? data : emptyRss } };
});
